#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""One-file installer for the Unified Agency Django upgrade.
Run from the Django project root, or pass --project-root.
"""
from __future__ import annotations
import argparse, base64, compileall, datetime, io, os, re, shutil, subprocess, sys, zipfile
from pathlib import Path

BUNDLE_B64 = ''


def say(s): print(s, flush=True)

def backup(path: Path, root: Path, backup_root: Path):
    if not path.exists(): return
    rel=path.relative_to(root)
    target=backup_root/rel
    target.parent.mkdir(parents=True,exist_ok=True)
    # Preserve the original pre-install file only once, even when patched in stages.
    if target.exists(): return
    shutil.copy2(path,target)

def replace_once(text, old, new, label):
    n=text.count(old)
    if n==0:
        if new in text: return text
        raise RuntimeError(f'Expected source snippet not found: {label}')
    if n>1: raise RuntimeError(f'Source snippet is not unique ({n} matches): {label}')
    return text.replace(old,new,1)

def append_marked(path: Path, patch: str, marker: str, root: Path, backup_root: Path):
    text=path.read_text(encoding='utf-8')
    if marker in text:
        say(f'[kept] {path.relative_to(root)} patch already installed')
        return
    backup(path,root,backup_root)
    path.write_text(text.rstrip()+"\n\n"+patch.strip()+"\n",encoding='utf-8')
    say(f'[patched] {path.relative_to(root)}')

def patch_views(path: Path, root: Path, backup_root: Path):
    text=path.read_text(encoding='utf-8')
    marker='# AGENCY_UPGRADE_ROLE_DEPARTMENT_GUARD'
    if marker in text:
        say('[kept] core/views.py guards already installed')
        return
    # Force non-GM users to submit reports only to their own department.
    needle='    dept = dept_by_key(f.get("dept"))\n'
    guard='    dept = dept_by_key(f.get("dept"))\n    if me.role != ROLE_GM and (not me.department_id or not dept or dept.pk != me.department_id):\n        return err("forbidden", 403)\n'
    if text.count(needle)<2: raise RuntimeError('Could not locate both document department checks in core/views.py')
    text=text.replace(needle,guard,2)
    # A manager-created account must have a real department and password, no demo defaults.
    needle='    dept = dept_by_key(d.get("dept"))\n'
    guard='    dept = dept_by_key(d.get("dept"))\n    if not dept:\n        return err("invalid")\n'
    if needle not in text: raise RuntimeError('Could not locate user_create department line')
    text=text.replace(needle,guard,1)
    # Make the UI distinguish a real SMTP email from Django's console email backend.
    mail_line='    return j({"ok": True, "mail_sent": mail_ok, "verify_required": settings.EMAIL_VERIFICATION_REQUIRED})'
    mail_new='    return j({"ok": True, "mail_sent": mail_ok, "mail_console": "console" in settings.EMAIL_BACKEND.lower(), "verify_required": settings.EMAIL_VERIFICATION_REQUIRED})'
    if mail_line in text: text=text.replace(mail_line,mail_new,1)
    # The resend endpoint reports whether the link was printed to server console.
    resend_start=text.find('def resend_view(')
    resend_end=text.find('\ndef verify_view(',resend_start)
    if resend_start>=0 and resend_end>resend_start:
        resend_block=text[resend_start:resend_end]
        resend_block=resend_block.replace('    return j({"ok": True})','    return j({"ok": True, "mail_console": "console" in settings.EMAIL_BACKEND.lower()})')
        text=text[:resend_start]+resend_block+text[resend_end:]
    # An attachment may be downloaded only if it belongs to an existing visible document,
    # a visible message, or a public news post. Orphan attachments are denied.
    needle=("    elif a.message_id:\n"
            "        if not visible_messages(me).filter(pk=a.message_id).exists():\n"
            "            return err(\"forbidden\", 403)\n"
            "    try:\n")
    replacement=("    elif a.message_id:\n"
            "        if not visible_messages(me).filter(pk=a.message_id).exists():\n"
            "            return err(\"forbidden\", 403)\n"
            "    elif a.post_id:\n"
            "        if not Post.objects.filter(pk=a.post_id).exists():\n"
            "            return err(\"forbidden\", 403)\n"
            "    else:\n"
            "        return err(\"forbidden\", 403)\n"
            "    try:\n")
    if needle not in text: raise RuntimeError('Could not locate file_view ownership checks')
    text=text.replace(needle,replacement,1)
    # Every active account may be mentioned, including the author themselves.
    old_mentions='mentioned = [u for u in services.find_mentions(text, active_users().exclude(pk=me.pk))]'
    new_mentions='mentioned = [u for u in services.find_mentions(text, active_users())]'
    if old_mentions in text:
        text=text.replace(old_mentions,new_mentions,1)
    # Do not hide old reports/posts behind arbitrary hard limits in state(); API is permission filtered.
    text=text.replace('.order_by("-created")[:1500]', '.order_by("-created")')
    text=text.replace('.order_by("-created")[:400]', '.order_by("-created")')
    backup(path,root,backup_root)
    path.write_text(text.rstrip()+"\n\n"+marker+"\n",encoding='utf-8')
    say('[patched] core/views.py (department guards, file permissions, all report/news rows)')

def patch_root_urls(url_path: Path, root: Path, backup_root: Path):
    text=url_path.read_text(encoding='utf-8')
    marker='# AGENCY_UPGRADE_URLS_INCLUDED'
    if marker in text:
        say(f'[kept] {url_path.relative_to(root)} URL include already installed')
        return
    import_line='from django.urls import include as _agency_include, path as _agency_path\n'
    if import_line.strip() not in text:
        text=import_line+text
    m=re.search(r'urlpatterns\s*=\s*\[',text)
    if not m: raise RuntimeError('Could not locate urlpatterns = [ in project urls.py')
    pos=m.end()
    text=text[:pos]+'\n    _agency_path("", _agency_include("core.upgrade_urls")),  # AGENCY_UPGRADE_URLS_INCLUDED\n'+text[pos:]
    backup(url_path,root,backup_root)
    url_path.write_text(text,encoding='utf-8')
    say(f'[patched] {url_path.relative_to(root)}')

def main():
    parser=argparse.ArgumentParser(description='Install Django agency security, AI, office and external-news upgrade')
    parser.add_argument('--project-root',default='.',help='Folder containing manage.py (default: current directory)')
    parser.add_argument('--no-migrate',action='store_true',help='Do not run makemigrations/migrate/check')
    args=parser.parse_args()
    root=Path(args.project_root).expanduser().resolve()
    required=[root/'manage.py',root/'core',root/'core/models.py',root/'core/views.py',root/'core/permissions.py',root/'core/services.py',root/'core/ai.py',root/'core/office.py']
    missing=[str(x) for x in required if not x.exists()]
    if missing:
        say('ERROR: دا فولډر د تمې وړ Django پروژه نه ښکاري. لاندې فایلونه نشته:')
        for x in missing: say('  - '+x)
        say('د Django پروژې اصلي فولډر --project-root ته ورکړه. دا بسته د بشپړې پروژې بدیل نه ده.')
        return 2
    stamp=datetime.datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    backup_root=root/'_agency_upgrade_backups'/stamp
    backup_root.mkdir(parents=True,exist_ok=True)
    say('Django پروژه: '+str(root))
    say('Backup: '+str(backup_root))
    blob=base64.b64decode(BUNDLE_B64)
    with zipfile.ZipFile(io.BytesIO(blob)) as z:
        for info in z.infolist():
            dest=root/info.filename
            if '..' in Path(info.filename).parts or dest.resolve().parent != (root/Path(info.filename)).resolve().parent:
                raise RuntimeError('Unsafe bundle path: '+info.filename)
            dest.parent.mkdir(parents=True,exist_ok=True)
            if info.filename.endswith('/__init__.py') and dest.exists() and info.file_size==0:
                say(f'[kept] {info.filename} (existing package init)')
                continue
            raw=z.read(info.filename)
            if dest.exists(): backup(dest,root,backup_root)
            dest.write_bytes(raw)
            say(f'[written] {info.filename}')
    # Model discovery: import the additional Django model from core.models.
    model_path=root/'core/models.py'
    model_text=model_path.read_text(encoding='utf-8')
    model_marker='# AGENCY_UPGRADE_EXTERNAL_NEWS_MODEL'
    if model_marker not in model_text:
        backup(model_path,root,backup_root)
        model_path.write_text(model_text.rstrip()+'\n\nfrom .news_models import ExternalNews  # AGENCY_UPGRADE_EXTERNAL_NEWS_MODEL\n',encoding='utf-8')
        say('[patched] core/models.py')
    else: say('[kept] core/models.py')
    # Patch role and mention utilities after their original definitions.
    for filename,patchfile,marker in [
      ('permissions.py','core/permissions_append.py.txt','# AGENCY UPGRADE: strict role-based server permissions'),
      ('services.py','core/services_append.py.txt','# AGENCY UPGRADE: @mention lookup across all authorized active users'),
      ('ai.py','core/ai_append.py.txt','# AGENCY UPGRADE: real Anthropic AI, restricted to the current user\'s data')]:
        append_marked(root/'core'/filename,(root/patchfile).read_text(encoding='utf-8'),marker,root,backup_root)
    patch_views(root/'core/views.py',root,backup_root)
    # Add the database table to Django admin, without double registration.
    admin_path=root/'core/admin.py'
    if admin_path.exists():
        admin_text=admin_path.read_text(encoding='utf-8')
        admin_marker='# AGENCY_UPGRADE_EXTERNAL_NEWS_ADMIN'
        if admin_marker not in admin_text:
            backup(admin_path,root,backup_root)
            admin_text += '\n\n# AGENCY_UPGRADE_EXTERNAL_NEWS_ADMIN\nfrom django.contrib import admin as _agency_admin\nfrom .models import ExternalNews as _AgencyExternalNews\ntry:\n    _agency_admin.site.register(_AgencyExternalNews)\nexcept _agency_admin.sites.AlreadyRegistered:\n    pass\n'
            admin_path.write_text(admin_text,encoding='utf-8')
            say('[patched] core/admin.py')
    # Append safe settings only when not already present.
    settings_path=None
    for p in root.glob('**/settings.py'):
        if 'ROOT_URLCONF' in p.read_text(encoding='utf-8',errors='ignore'):
            settings_path=p;break
    if settings_path is None: raise RuntimeError('Could not find project settings.py containing ROOT_URLCONF')
    st=settings_path.read_text(encoding='utf-8')
    additions=[]
    for name,line in [
      ('NEWS_FEEDS_JSON','NEWS_FEEDS_JSON = os.environ.get("NEWS_FEEDS_JSON", "")'),
      ('NEWS_AUTOFETCH','NEWS_AUTOFETCH = os.environ.get("NEWS_AUTOFETCH", "1").strip().lower() in ("1", "true", "yes", "on")'),
      ('NEWS_FETCH_INTERVAL_MIN','NEWS_FETCH_INTERVAL_MIN = int(os.environ.get("NEWS_FETCH_INTERVAL_MIN", "15"))'),
      ('NEWS_KEEP_DAYS','NEWS_KEEP_DAYS = int(os.environ.get("NEWS_KEEP_DAYS", "14"))')]:
        if not re.search(r'^\s*'+name+r'\s*=',st,re.M): additions.append(line)
    settings_changed=False
    # The model name in the previously supplied settings example is not a current Anthropic API model ID.
    old_model='AI_MODEL = _env("AI_MODEL", "claude-sonnet-5-5")'
    if old_model in st:
        st=st.replace(old_model,'AI_MODEL = _env("AI_MODEL", "claude-sonnet-5")',1)
        settings_changed=True
        say('[updated] AI_MODEL default to claude-sonnet-5')
    if additions:
        if 'import os' not in st: additions.insert(0,'import os')
        st=st.rstrip()+'\n\n# AGENCY_UPGRADE_NEWS_SETTINGS\n'+'\n'.join(additions)+'\n'
        settings_changed=True
    if settings_changed:
        backup(settings_path,root,backup_root)
        settings_path.write_text(st,encoding='utf-8')
        say(f'[patched] {settings_path.relative_to(root)}')
    # Root URL config: find the module file mentioned in ROOT_URLCONF.
    settings_now=settings_path.read_text(encoding='utf-8')
    mm=re.search(r'ROOT_URLCONF\s*=\s*["\']([\w.]+)["\']',settings_now)
    if not mm: raise RuntimeError('Could not parse ROOT_URLCONF in settings.py')
    mod=mm.group(1).split('.')
    url_path=root.joinpath(*mod).with_suffix('.py')
    if not url_path.exists(): raise RuntimeError('Root URL file not found: '+str(url_path))
    patch_root_urls(url_path,root,backup_root)
    # Migrations package required for Django's makemigrations command.
    mig=root/'core/migrations'
    mig.mkdir(exist_ok=True)
    (mig/'__init__.py').touch(exist_ok=True)
    # Compile generated and patched Python before migrations.
    ok=compileall.compile_dir(str(root/'core'),quiet=1,force=True)
    if not ok: raise RuntimeError('Python compileall failed; restore from backup before deployment')
    say('Python syntax compilation: OK')
    if not args.no_migrate:
        cmds=[[sys.executable,'manage.py','makemigrations','core'],[sys.executable,'manage.py','migrate'],[sys.executable,'manage.py','check']]
        for cmd in cmds:
            say('Running: '+' '.join(cmd))
            done=subprocess.run(cmd,cwd=str(root))
            if done.returncode:
                say('Migration/check failed. Backup is available at: '+str(backup_root))
                say('Resolve the error, then run makemigrations core, migrate, and check manually.')
                return done.returncode
    say('\nنصب فایلونه بشپړ شول. backup: '+str(backup_root))
    say('اوس requirements نصب کړه، migrations اجرا کړه که پورته نه دي اجرا شوي، او fetch_news_loop د system service په توګه فعال کړه.')
    return 0

if __name__=='__main__':
    try: raise SystemExit(main())
    except KeyboardInterrupt: raise SystemExit(130)
    except Exception as exc:
        print('INSTALL ERROR:',exc,file=sys.stderr)
        raise SystemExit(1)
